Current transform code:

def transform(grid):
    """Transform a 2/4 grid according to ARC puzzle rules.
    - 2s always stay as 2s
    - 4s that are sandwiched between 2s (horizontally OR vertically) become 3s
    - Other 4s (and other values) stay the same
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    result = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 2:
                result[r][c] = 2
            else:
                # Check horizontal sandwich
                has_left_2 = False
                for dc in range(c-1, -1, -1):
                    if grid[r][dc] == 2:
                        has_left_2 = True
                        break
                has_right_2 = False
                for dc in range(c+1, cols):
                    if grid[r][dc] == 2:
                        has_right_2 = True
                        break

                sandwiched_horz = has_left_2 and has_right_2

                if sandwiched_horz:
                    result[r][c] = 3
                else:
                    # Check vertical sandwich
                    has_up_2 = False
                    for dr in range(r-1, -1, -1):
                        if grid[dr][c] == 2:
                            has_up_2 = True
                            break
                    has_down_2 = False
                    for dr in range(r+1, rows):
                        if grid[dr][c] == 2:
                            has_down_2 = True
                            break

                    sandwiched_vert = has_up_2 and has_down_2
                    result[r][c] = 3 if sandwiched_vert else val

    return result

